def add_user_ids(apps, schema_editor):
    """A sender's name in another script is followed by the user id from the address (util.display_name)."""
    from llmwiki.util import display_name
    Email = apps.get_model("llmwiki", "Email")
    rows = []
    for e in Email.objects.only("id", "from_name", "from_addr").iterator(chunk_size=1000):
        new = display_name(e.from_name, e.from_addr)[:320]
        if new != e.from_name:
            e.from_name = new
            rows.append(e)
    Email.objects.bulk_update(rows, ["from_name"], batch_size=500)


